int GetMultiIndex(std::vector <int> &idx_vec) const
{
	idx_vec.clear();
	// MT2009_PLUS_CHEST_PICK_V1 (draw), server-patches/balathor: a group with "Pick N" (no Type) gives N different
	// rows an opening, drawn one after another by their weights without putting a drawn row back
	// (a gold / exp / sNNN row is one of the N like any other); fewer rows than N = all of them.
	if (m_bType == NORMAL && m_iPickCount > 0 && !m_vecProbs.empty())
	{
		std::vector<int> weights(m_vecProbs.size());
		int total = 0;
		for (size_t i = 0; i < m_vecProbs.size(); ++i)
		{
			weights[i] = std::max(0, m_vecProbs[i] - (i ? m_vecProbs[i - 1] : 0));
			total += weights[i];
		}
		const int want = std::min(m_iPickCount, (int) weights.size());
		for (int k = 0; k < want && total > 0; ++k)
		{
			int n = number(1, total);
			size_t i = 0;
			for (; i + 1 < weights.size(); ++i)
			{
				if (n <= weights[i])
					break;
				n -= weights[i];
			}
			idx_vec.emplace_back((int) i);
			total -= weights[i];
			weights[i] = 0;
		}
		return (int) idx_vec.size();
	}

